#!/usr/bin/env bash
set -euo pipefail; R="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; P="${1:?program hex required}"; E="${2:?expected signature hex required}"; M="${3:-100}";mkdir -p "$R/build";REQ=(alu.sv regfile.sv extend.sv controller.sv pc_unit.sv branch_unit.sv memory_access.sv datapath.sv);for x in "${REQ[@]}";do [[ -f "$R/rtl/$x" ]]||{ echo "error: missing required module $R/rtl/$x - generate all four new modules and copy your four A1 modules into rtl/ before running the datapath";exit 2;};done;iverilog -g2012 -s datapath_tb -o "$R/build/datapath.vvp" "$R"/rtl/*.sv "$R/testbench/datapath_tb.sv";OUT="$(vvp "$R/build/datapath.vvp" "+PROGRAM=$P" "+EXPECT=$E" "+MAX_CYCLES=$M")"; echo "$OUT"; if echo "$OUT" | grep -q "^FAIL" || ! echo "$OUT" | grep -q "^PASS"; then echo ">>> RESULT: FAIL"; exit 1; fi; echo ">>> RESULT: PASS"
